// Collect one digest payload per recipient for the week just gone.
//
// Reads straight from Supabase's REST API with the service-role key, the same
// way the retired scraper workflow did. Emits one item per user who has at
// least one application worth telling them about — users with nothing new are
// dropped here, so nobody receives an empty email.

const SUPABASE_URL = $env.SUPABASE_URL || 'https://vinwnykuumifpctdjxbu.supabase.co';
const KEY = $env.SUPABASE_SERVICE_ROLE_KEY;

if (!KEY) throw new Error('SUPABASE_SERVICE_ROLE_KEY is not set in this n8n environment.');

const headers = { apikey: KEY, Authorization: 'Bearer ' + KEY };

async function get(table, qs) {
  return this.helpers.httpRequest({
    method: 'GET',
    url: SUPABASE_URL + '/rest/v1/' + table,
    headers,
    qs,
    json: true,
  });
}

// ── Reporting window ────────────────────────────────────────────────────────
// The seven whole days ending yesterday. Running at 06:00 Monday, that means
// last Monday through Sunday — a complete week, never a partial one, and it
// can't double-count if the workflow is re-run later the same day.
const today = new Date();
const end = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate()));
const start = new Date(end);
start.setUTCDate(start.getUTCDate() - 7);
const iso = (d) => d.toISOString().slice(0, 10);
const periodStart = iso(start);
const periodEnd = iso(new Date(end.getTime() - 86400000)); // inclusive last day

// ── 1. Every active tracked area ────────────────────────────────────────────
const areas = await get.call(this, 'tracked_areas', {
  is_active: 'eq.true',
  select: 'user_id,label,postcode,council_slug,min_band',
});
if (!areas.length) return [];

// ── 2. The people who own them ──────────────────────────────────────────────
// Homeowners included deliberately: the free tier is sold on "a weekly email
// digest", so gating this on pro access would make that claim false.
const userIds = [...new Set(areas.map((a) => a.user_id))];
const profiles = await get.call(this, 'profiles', {
  id: 'in.(' + userIds.join(',') + ')',
  select: 'id,email,digest_day',
});
const emailById = new Map(profiles.map((p) => [p.id, p.email]));

// ── 3. Applications published in those councils during the window ───────────
const slugs = [...new Set(areas.map((a) => a.council_slug))];
const apps = await get.call(this, 'planning_applications', {
  council_slug: 'in.(' + slugs.map((s) => '"' + s + '"').join(',') + ')',
  // Both bounds in one and=(...) group. A JS object can't carry two
  // application_date keys, and PostgREST would only see the last one.
  and: '(application_date.gte.' + periodStart + ',application_date.lte.' + periodEnd + ')',
  select: 'id,council_slug,reference,address,description,status,application_date,band,score',
  order: 'application_date.desc',
  limit: '2000',
});

// Bucket by council once, rather than re-scanning the list per area.
const byCouncil = new Map();
for (const a of apps) {
  if (!byCouncil.has(a.council_slug)) byCouncil.set(a.council_slug, []);
  byCouncil.get(a.council_slug).push(a);
}

// Mirrors filterByBand in components/dashboard/TrackedAreasList.tsx, so the
// email and the dashboard agree on what counts as relevant for an area.
function passesBand(app, minBand) {
  if (minBand === 'WARM_PLUS') return app.band === 'HOT' || app.band === 'WARM';
  if (minBand === 'HOT_ONLY') return app.band === 'HOT';
  return true; // 'ALL'
}

// ── 4. One payload per user ─────────────────────────────────────────────────
const out = [];

for (const userId of userIds) {
  const email = emailById.get(userId);
  if (!email) continue;

  const myAreas = areas.filter((a) => a.user_id === userId);
  // An application can sit in two areas that share a council. Keep the first
  // area that claims it so it's listed once, attributed somewhere sensible.
  const seen = new Set();
  const items = [];

  for (const area of myAreas) {
    const councilApps = byCouncil.get(area.council_slug) || [];
    for (const app of councilApps) {
      if (seen.has(app.id)) continue;
      if (!passesBand(app, area.min_band)) continue;
      seen.add(app.id);
      items.push({
        id: app.id,
        reference: app.reference,
        description: app.description,
        address: app.address,
        status: app.status,
        applicationDate: app.application_date,
        band: app.band,
        councilSlug: app.council_slug,
        areaLabel: area.label || area.postcode,
      });
    }
  }

  if (!items.length) continue; // nothing to say — send nothing

  // HOT first, then most recent, so the top of the email is the best of it.
  const rank = { HOT: 0, WARM: 1, COLD: 2 };
  items.sort((a, b) => {
    const r = (rank[a.band] ?? 3) - (rank[b.band] ?? 3);
    if (r !== 0) return r;
    return String(b.applicationDate || '').localeCompare(String(a.applicationDate || ''));
  });

  out.push({
    json: {
      userId,
      email,
      periodStart,
      periodEnd,
      areaCount: myAreas.length,
      areaLabels: [...new Set(myAreas.map((a) => a.label || a.postcode))],
      applicationCount: items.length,
      items,
    },
  });
}

return out;

// Build and send one digest per recipient, then record it in the digests
// table so Settings → Digest history has something to show.
//
// Email HTML rules that differ from the app: tables for layout, every style
// inline, no external stylesheet, 600px max width. IBM Plex is named first in
// the font stack for the clients that support webfont-less system matching,
// with the app's own fallbacks behind it.

const RESEND_KEY = $env.RESEND_KEY || $env.RESEND_API_KEY;
const SUPABASE_URL = $env.SUPABASE_URL || 'https://vinwnykuumifpctdjxbu.supabase.co';
const SUPABASE_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;
const SITE_URL = $env.SITE_URL || 'https://planningping.com';
const FROM = $env.DIGEST_FROM || 'PlanningPing <notifications@kelwave.co.uk>';

if (!RESEND_KEY) throw new Error('RESEND_KEY is not set in this n8n environment.');
if (!SUPABASE_KEY) throw new Error('SUPABASE_SERVICE_ROLE_KEY is not set in this n8n environment.');

// Design tokens — kept in step with @theme in app/globals.css.
const C = {
  ink: '#202124',
  muted: '#6b6c70',
  faint: '#757579',
  border: '#d6e4fb',
  borderSoft: '#e3e3e7',
  sunken: '#f8f8f9',
  page: '#f1f1f3',
  card: '#ffffff',
  brand: '#2563eb',
  brandDark: '#1d4ed8',
  brandTint: '#eaf0ff',
};
const SANS = "'IBM Plex Sans',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const MONO = "'IBM Plex Mono','SF Mono',SFMono-Regular,ui-monospace,Menlo,Consolas,monospace";

const MAX_SHOWN = 8;

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function truncate(s, n) {
  const t = String(s || '').trim();
  if (t.length <= n) return t;
  return t.slice(0, n).replace(/\s+\S*$/, '') + '…';
}

function niceDate(isoDate) {
  if (!isoDate) return '';
  const d = new Date(isoDate + 'T00:00:00Z');
  if (isNaN(d)) return esc(isoDate);
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  return d.getUTCDate() + ' ' + months[d.getUTCMonth()] + ' ' + d.getUTCFullYear();
}

// Status pill — same keyword matching and tones as lib/statusStyle.ts.
function statusPill(status) {
  if (!status) return '';
  const s = String(status).toLowerCase();
  let bg = '#f1f1f3', fg = '#55565b';
  if (/approv|grant|permit/.test(s)) { bg = '#ecfdf5'; fg = '#047857'; }
  else if (/refus|reject|withdraw|dismiss/.test(s)) { bg = '#fef2f2'; fg = '#b91c1c'; }
  else if (/pending|await|consult|valid|registered/.test(s)) { bg = '#fffbeb'; fg = '#b45309'; }
  return '<span style="display:inline-block;background:' + bg + ';color:' + fg +
    ';font-size:11px;font-weight:600;line-height:1;padding:5px 9px;border-radius:999px;white-space:nowrap;">' +
    esc(status) + '</span>';
}

function bandPill(band) {
  if (!band || band === 'COLD') return '';
  const tone = band === 'HOT'
    ? { bg: '#fef2f2', fg: '#b91c1c' }
    : { bg: '#fffbeb', fg: '#b45309' };
  return '<span style="display:inline-block;background:' + tone.bg + ';color:' + tone.fg +
    ';font-size:10px;font-weight:700;letter-spacing:.04em;line-height:1;padding:4px 7px;border-radius:999px;margin-left:6px;">' +
    esc(band) + '</span>';
}

function card(a) {
  return [
    '<tr><td style="padding:0 0 12px;">',
      '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:separate;border:1px solid ', C.border, ';border-radius:10px;">',
        '<tr><td style="padding:16px 18px;">',
          '<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>',
            '<td style="font-family:', MONO, ';font-size:12px;font-weight:600;color:', C.brand, ';">',
              esc(a.reference), bandPill(a.band),
            '</td>',
            '<td align="right" style="font-family:', SANS, ';font-size:11px;color:', C.faint, ';white-space:nowrap;">',
              esc(niceDate(a.applicationDate)),
            '</td>',
          '</tr></table>',
          '<div style="font-family:', SANS, ';font-size:14px;line-height:1.5;color:', C.ink, ';margin:8px 0 0;">',
            esc(truncate(a.description || 'No description', 180)),
          '</div>',
          a.address
            ? '<div style="font-family:' + SANS + ';font-size:12px;line-height:1.5;color:' + C.muted + ';margin:6px 0 0;">' + esc(a.address) + '</div>'
            : '',
          '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:12px 0 0;"><tr>',
            '<td>', statusPill(a.status), '</td>',
            '<td align="right" style="font-family:', SANS, ';font-size:11px;color:', C.faint, ';">',
              esc(a.areaLabel),
            '</td>',
          '</tr></table>',
        '</td></tr>',
      '</table>',
    '</td></tr>',
  ].join('');
}

function buildHtml(d) {
  const shown = d.items.slice(0, MAX_SHOWN);
  const remaining = d.items.length - shown.length;
  const n = d.applicationCount;
  const areaWord = d.areaCount === 1 ? 'territory' : 'territories';

  return [
    '<!doctype html><html><head><meta charset="utf-8">',
    '<meta name="viewport" content="width=device-width,initial-scale=1">',
    '<meta name="color-scheme" content="light only"><meta name="supported-color-schemes" content="light">',
    '<title>Your PlanningPing digest</title></head>',
    '<body style="margin:0;padding:0;background:', C.page, ';">',
    // Preheader — what shows in the inbox list next to the subject.
    '<div style="display:none;max-height:0;overflow:hidden;opacity:0;">',
      n, ' new application', n === 1 ? '' : 's', ' across your ', d.areaCount, ' ', areaWord, '.',
    '</div>',
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:', C.page, ';">',
      '<tr><td align="center" style="padding:28px 16px;">',
        '<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:', C.card, ';border:1px solid ', C.border, ';border-radius:14px;">',

          // Header
          '<tr><td style="padding:24px 26px 18px;border-bottom:1px solid ', C.border, ';">',
            '<div style="font-family:', SANS, ';font-size:15px;font-weight:600;letter-spacing:-.02em;color:', C.ink, ';">',
              'Planning<span style="color:', C.brand, ';">Ping</span>',
            '</div>',
            '<div style="font-family:', SANS, ';font-size:20px;font-weight:600;letter-spacing:-.02em;color:', C.ink, ';margin:14px 0 0;">',
              n, ' new application', n === 1 ? '' : 's', ' this week',
            '</div>',
            '<div style="font-family:', SANS, ';font-size:13px;line-height:1.65;color:', C.muted, ';margin:6px 0 0;">',
              'Across your ', d.areaCount, ' ', areaWord, ' · ', esc(niceDate(d.periodStart)), ' to ', esc(niceDate(d.periodEnd)),
            '</div>',
          '</td></tr>',

          // Applications
          '<tr><td style="padding:20px 26px 4px;">',
            '<table role="presentation" width="100%" cellpadding="0" cellspacing="0">',
              shown.map(card).join(''),
            '</table>',
            remaining > 0
              ? '<div style="font-family:' + SANS + ';font-size:13px;color:' + C.muted + ';padding:2px 0 12px;">and ' + remaining + ' more in your dashboard.</div>'
              : '',
          '</td></tr>',

          // CTA
          '<tr><td style="padding:6px 26px 26px;">',
            '<a href="', SITE_URL, '/dashboard" style="display:inline-block;background:', C.brand, ';color:#ffffff;font-family:', SANS, ';font-size:14px;font-weight:500;text-decoration:none;padding:11px 18px;border-radius:6px;">',
              'Open your dashboard',
            '</a>',
          '</td></tr>',

          // Footer
          '<tr><td style="padding:18px 26px 22px;border-top:1px solid ', C.border, ';background:', C.sunken, ';border-radius:0 0 14px 14px;">',
            '<div style="font-family:', SANS, ';font-size:11px;line-height:1.65;color:', C.faint, ';">',
              'PlanningPing is an alerting tool, not professional advice. Planning data is collected from public portals and may be incomplete, delayed, or inaccurate. Always verify against the official planning authority before acting.',
            '</div>',
            '<div style="font-family:', SANS, ';font-size:11px;line-height:1.65;color:', C.faint, ';margin:10px 0 0;">',
              '<a href="', SITE_URL, '/settings" style="color:', C.muted, ';">Manage your digest</a> · ',
              '<a href="', SITE_URL, '/terms" style="color:', C.muted, ';">Terms</a> · ',
              '<a href="', SITE_URL, '/privacy" style="color:', C.muted, ';">Privacy</a>',
            '</div>',
          '</td></tr>',

        '</table>',
      '</td></tr>',
    '</table></body></html>',
  ].join('');
}

// ── Send + record, one recipient at a time ──────────────────────────────────
// Failures are collected rather than thrown: one bad address must not stop
// the rest of the run.
const results = [];

for (const item of $input.all()) {
  const d = item.json;
  const subject = d.applicationCount + ' new planning application' +
    (d.applicationCount === 1 ? '' : 's') + ' in your ' +
    (d.areaCount === 1 ? 'territory' : 'territories');

  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.resend.com/emails',
      headers: { Authorization: 'Bearer ' + RESEND_KEY, 'Content-Type': 'application/json' },
      body: { from: FROM, to: [d.email], subject, html: buildHtml(d) },
      json: true,
    });

    // Only recorded once Resend has accepted it, so digest history reflects
    // what was actually sent rather than what was attempted.
    await this.helpers.httpRequest({
      method: 'POST',
      url: SUPABASE_URL + '/rest/v1/digests',
      headers: {
        apikey: SUPABASE_KEY,
        Authorization: 'Bearer ' + SUPABASE_KEY,
        'Content-Type': 'application/json',
        Prefer: 'return=minimal',
      },
      body: {
        user_id: d.userId,
        period_start: d.periodStart,
        period_end: d.periodEnd,
        application_count: d.applicationCount,
        summary: subject,
      },
      json: true,
    });

    results.push({ json: { email: d.email, sent: true, id: res && res.id ? res.id : null, applicationCount: d.applicationCount } });
  } catch (err) {
    results.push({ json: { email: d.email, sent: false, error: String(err && err.message ? err.message : err) } });
  }
}

return results;
